	statevars {
		int count;
	}

	msgsrv initial() {
		count = 0;
	}

	msgsrv Increment() {
		count = count + 1;
		sender.ValueResponse(count);
	}

	msgsrv Decrement() {
		count = count - 1;
		sender.ValueResponse(count);
	}

	msgsrv GetValue() {
		sender.ValueResponse(count);
	}
}

reactiveclass Client {
	knownrebecs {
		Counter c;
	}
	statevars {
		int clientId;
	}

	msgsrv initial(int id) {
		clientId = id;

		c.Increment();
		c.Increment();
		c.GetValue();
	}

	msgsrv ValueResponse(int value) {
		// no-op
	}
}

main {
	Counter counter():();
	Client client1(counter):(1);
	Client client2(counter):(2);
}

